def sharing_violation(path: Path, *args: object, **kwargs: object) -> None:
            nonlocal attempts
            if path == lock_path and attempts < 3:
                attempts += 1
                raise PermissionError(13, "fixture sharing violation", str(path), 32)
            original_unlink(path, *args, **kwargs)

